     1→//! rlibc-x2: A libc replacement for Rust std applications
     2→//!
     3→//! This crate provides the libc symbols needed to run Rust programs
     4→//! that use the standard library, without linking to glibc.
     5→//!
     6→//! # Usage
     7→//!
     8→//! Add to your Cargo.toml:
     9→//! ```toml
    10→//! [dependencies]
    11→//! rlibc-x2 = { path = "../rlibc-x2" }
    12→//! ```
    13→//!
    14→//! And in your build.rs:
    15→//! ```rust
    16→//! fn main() {
    17→//!     println!("cargo:rustc-link-arg=-static");
    18→//!     println!("cargo:rustc-link-arg=-nostdlib");
    19→//!     println!("cargo:rustc-link-arg=-nodefaultlibs");
    20→//!     println!("cargo:rustc-link-arg=-e_start");
    21→//!     println!("cargo:rustc-link-arg=-Wl,--undefined=_start");
    22→//!     println!("cargo:rustc-link-arg=-Wl,--undefined=__libc_start_main");
    23→//! }
    24→//! ```
    25→
    26→#![no_std]
    27→
    28→pub mod errno;
    29→pub mod io;
    30→pub mod memory;
    31→pub mod process;
    32→pub mod signal;
    33→pub mod syscall;
    34→pub mod thread;
    35→
    36→// Re-export key functions
    37→pub use process::exit;
    38→
    39→// Note: We don't provide a panic handler because std provides one.
    40→// rlibc-x2 is designed to be used WITH std, just replacing libc.
    41→
    42→// Stubs for functions we haven't implemented yet
    43→// These print a message and exit so we know what's missing
    44→
    45→macro_rules! stub {
    46→    ($name:ident, $ret:ty) => {
    47→        #[unsafe(no_mangle)]
    48→        pub extern "C" fn $name() -> $ret {
    49→            let msg = concat!("STUB: ", stringify!($name), "\n");
    50→            io::write(2, msg.as_ptr(), msg.len());
    51→            process::exit(99)
    52→        }
    53→    };
    54→    ($name:ident) => {
    55→        #[unsafe(no_mangle)]
    56→        pub extern "C" fn $name() -> ! {
    57→            let msg = concat!("STUB: ", stringify!($name), "\n");
    58→            io::write(2, msg.as_ptr(), msg.len());
    59→            process::exit(99)
    60→        }
    61→    };
    62→}
    63→
    64→// File system stubs
    65→stub!(close, i32);
    66→stub!(dup, i32);
    67→stub!(fcntl, i32);
    68→stub!(fstat64, i32);
    69→stub!(lseek64, i64);
    70→stub!(open64, i32);
    71→stub!(stat64, i32);
    72→stub!(getcwd, *mut u8);
    73→stub!(readlink, isize);
    74→stub!(realpath, *mut u8);
    75→
    76→// Environment stubs
    77→stub!(getenv, *const u8);
    78→stub!(getauxval, usize);
    79→
    80→// Memory mapping stubs
    81→stub!(mmap64, *mut u8);
    82→stub!(mprotect, i32);
    83→stub!(munmap, i32);
    84→
    85→// Generic syscall - all x86_64 Linux syscalls use at most 6 arguments
    86→#[unsafe(no_mangle)]
    87→pub extern "C" fn syscall(
    88→    num: i64,
    89→    arg1: u64,
    90→    arg2: u64,
    91→    arg3: u64,
    92→    arg4: u64,
    93→    arg5: u64,
    94→    arg6: u64,
    95→) -> i64 {
    96→    unsafe { syscall::syscall6(num as u64, arg1, arg2, arg3, arg4, arg5, arg6) as i64 }
    97→}
    98→
    99→// Unwinding stubs (for panic/backtrace)
   100→stub!(_Unwind_Backtrace, i32);
   101→stub!(_Unwind_DeleteException);
   102→stub!(_Unwind_GetDataRelBase, usize);
   103→stub!(_Unwind_GetIP, usize);
   104→stub!(_Unwind_GetIPInfo, usize);
