pub extern "C" fn __xpg_strerror_r(_errnum: i32, _buf: *mut u8, _buflen: usize) -> i32 {
    // TODO: implement properly
    -1
}

#[unsafe(no_mangle)]
pub extern "C" fn strlen(s: *const u8) -> usize {
    let mut len = 0;
    unsafe {
        while *s.add(len) != 0 {
            len += 1;
        }
    }
    len
}

